/** One side of what every app shares: the neutrals and the signals. */
@Immutable
public class Neutrals internal constructor(
    /** The page. */
    public val background: Color,
    /** A plane over the page: a sheet, a card, a bar. */
    public val surface: Color,
    /** The faintest step a container takes off the page. */
    public val containerLowest: Color,
    /** A container one step off the page. */
    public val containerLow: Color,
    /** A container: a field, a grouped list's rows. */
    public val container: Color,
    /** A container a step further: a chip, a track. */
    public val containerHigh: Color,
    /** The furthest step: a pressed row, a meter's track. */
    public val containerHighest: Color,
    /** The fill of a glass chip, menu and sheet. */
    public val glass: Color,
    /** The edge of a control: a field, an unchecked box. */
    public val outline: Color,
    /** A divider, and a cover's edge. */
    public val hairline: Color,
    /** Text. */
    public val ink: Color,
    /** Secondary text: a subtitle, a count, a caption. */
    public val quiet: Color,
    /** What cannot be pressed. */
    public val disabled: Color,
    /** What dims the page under a dialog. */
    public val scrim: Color,
    /** A snackbar: the other side's surface. */
    public val inverseSurface: Color,
    /** Text on the inverse surface. */
    public val inverseInk: Color,
    /** Wrong: an error, an overspent amount. */
    public val error: Color,
    /** What is written on the error colour. */
    public val onError: Color,
    /** A quiet container for an error. */
    public val errorContainer: Color,
    /** What is written on that. */
    public val onErrorContainer: Color,
    /** Worth a look: an amount short of its target. */
    public val caution: Color,
    /** What is written on the caution colour. */
    public val onCaution: Color,
    /** A quiet container for a caution. */
    public val cautionContainer: Color,
    /** What is written on that. */
    public val onCautionContainer: Color,
    /** Good: money with a job, a goal met. */
    public val positive: Color,
)

