/** An app's accent: the one colour that is the app's own, and the squares it draws. */
public enum class Accent {
    Gold,
    Green,
    Blue;

    /** The accent for the side asked. */
    public fun colors(dark: Boolean): AccentColors =
        when (this) {
            Gold -> if (dark) GoldDark else GoldLight
            Green -> if (dark) GreenDark else GreenLight
            Blue -> if (dark) BlueDark else BlueLight
        }

    /** The derived squares' gradients for the side asked. */
    public fun art(dark: Boolean): List<Pair<Color, Color>> =
        when (this) {
            Gold -> if (dark) ArtSets.GoldDark else ArtSets.GoldLight
            Green -> if (dark) ArtSets.GreenDark else ArtSets.GreenLight
            Blue -> if (dark) ArtSets.NeutralDark else ArtSets.NeutralLight
        }
}

