/**
 * The Material scheme an app is drawn in: the shared neutrals and signals, with `accent` in
 * the primary slots, a neutral grey in the secondary (so a tonal button on an accent card
 * still shows) and the caution in the tertiary. Nothing is tinted by elevation (`surfaceTint`
 * is the surface), and `surfaceBright` is the glass.
 */
public fun arkuiScheme(accent: Accent, dark: Boolean): ColorScheme {
    val n = Tokens.of(dark)
    val a = accent.colors(dark)
    val inverse = accent.colors(!dark).accent
    return if (dark) {
        darkColorScheme(
            primary = a.accent,
            onPrimary = a.onAccent,
            primaryContainer = a.accentContainer,
            onPrimaryContainer = a.onAccentContainer,
            inversePrimary = inverse,
            secondary = n.quiet,
            onSecondary = n.background,
            secondaryContainer = n.containerHighest,
            onSecondaryContainer = n.ink,
            tertiary = n.caution,
            onTertiary = n.onCaution,
            tertiaryContainer = n.cautionContainer,
            onTertiaryContainer = n.onCautionContainer,
            background = n.background,
            onBackground = n.ink,
            surface = n.surface,
            onSurface = n.ink,
            surfaceVariant = n.containerHigh,
            onSurfaceVariant = n.quiet,
            surfaceTint = n.surface,
            inverseSurface = n.inverseSurface,
            inverseOnSurface = n.inverseInk,
            error = n.error,
            onError = n.onError,
            errorContainer = n.errorContainer,
            onErrorContainer = n.onErrorContainer,
            outline = n.outline,
            outlineVariant = n.hairline,
            scrim = n.scrim,
            surfaceBright = n.glass,
            surfaceDim = n.background,
            surfaceContainer = n.container,
            surfaceContainerHigh = n.containerHigh,
            surfaceContainerHighest = n.containerHighest,
            surfaceContainerLow = n.containerLow,
            surfaceContainerLowest = n.containerLowest,
        )
    } else {
        lightColorScheme(
            primary = a.accent,
            onPrimary = a.onAccent,
            primaryContainer = a.accentContainer,
            onPrimaryContainer = a.onAccentContainer,
            inversePrimary = inverse,
            secondary = n.quiet,
            onSecondary = n.background,
            secondaryContainer = n.containerHighest,
            onSecondaryContainer = n.ink,
            tertiary = n.caution,
            onTertiary = n.onCaution,
            tertiaryContainer = n.cautionContainer,
            onTertiaryContainer = n.onCautionContainer,
            background = n.background,
            onBackground = n.ink,
            surface = n.surface,
            onSurface = n.ink,
            surfaceVariant = n.containerHigh,
            onSurfaceVariant = n.quiet,
            surfaceTint = n.surface,
            inverseSurface = n.inverseSurface,
            inverseOnSurface = n.inverseInk,
            error = n.error,
            onError = n.onError,
            errorContainer = n.errorContainer,
            onErrorContainer = n.onErrorContainer,
            outline = n.outline,
            outlineVariant = n.hairline,
            scrim = n.scrim,
            surfaceBright = n.glass,
            surfaceDim = n.containerHighest,
            surfaceContainer = n.container,
            surfaceContainerHigh = n.containerHigh,
            surfaceContainerHighest = n.containerHighest,
            surfaceContainerLow = n.containerLow,
            surfaceContainerLowest = n.containerLowest,
        )
    }
}
